import (
	"fmt"
	"sync"
)

func Tee(in <-chan int) (<-chan int, <-chan int) {
	out1 := make(chan int)
	out2 := make(chan int)

	go func() {
		defer close(out1)
		defer close(out2)

		for val := range in {
			// Синхронная отправка в оба канала без блокировки одним из них
			var ch1, ch2 chan int = out1, out2
			for i := 0; i < 2; i++ {
				select {
				case ch1 <- val:
					ch1 = nil // Отправлено в первый канал -> отключаем
				case ch2 <- val:
					ch2 = nil // Отправлено во второй канал -> отключаем
				}
			}
		}
	}()

	return out1, out2
}

func main() {
	in := make(chan int, 3)
	in <- 10; in <- 20; in <- 30; close(in)

	t1, t2 := Tee(in)
	var wg sync.WaitGroup

	wg.Add(2)
	go func() {
		defer wg.Done()
		for v := range t1 {
			fmt.Printf(" [Branch 1] %d\n", v)
		}
	}()

	go func() {
		defer wg.Done()
		for v := range t2 {
			fmt.Printf(" [Branch 2] %d\n", v)
		}
	}()

	wg.Wait()
}

